import 'metronome_pattern.dart';

/// Selectable click sounds. Samples are generated by
/// `tool/generate_clicks.dart` as `assets/clicks/<name>_<accent|normal>.wav`.
enum ClickSound {
  classic('Classic'),
  woodblock('Woodblock'),
  beep('Beep'),
  cowbell('Cowbell');

  const ClickSound(this.label);

  final String label;

  /// Soft subdivision clicks reuse the normal sample at lower volume.
  String assetFor(StepLevel level) =>
      'assets/clicks/${name}_${level == StepLevel.accent ? 'accent' : 'normal'}.wav';
}
